import * as readline from "node:readline";
import { Readable } from "node:stream";
async function main(): Promise<void> {
  const rl2 = readline.createInterface({ input: Readable.from(["a\nb\n"]) });
  rl2.on("line", (l: string) => console.log("line", l));
  await new Promise((r) => rl2.on("close", r));
  const rlp = await import("node:readline/promises");
  const rl3 = rlp.createInterface({ input: Readable.from(["answer\n"]) });
  console.log(await rl3.question("q? "));
  rl3.close();
}
